#include <iostream>
#include <cmath>
using namespace std;

int main() {
    int N;
    cin >> N;

    int ans = 100;

    for (int i = 0; i <= 100; i += 5) {
        if (abs(N - ans) > abs(N - i)) {
            ans = i;
        }
    }

    cout << ans << endl;

    return 0;
}
